diff --git a/source/pagination-target.ts b/source/pagination-target.ts
new file mode 100644
index 0000000..6b748c8
--- /dev/null
+++ b/source/pagination-target.ts
@@ -0,0 +1,27 @@
+import parseLinkHeader from './core/parse-link-header.js';
+
+/**
+Returns the absolute URL of the first Link header entry whose `rel`
+parameter includes `relation` as a whitespace-separated value, or `null`
+when the header is absent, empty, or has no matching entry.
+*/
+// eslint-disable-next-line @typescript-eslint/ban-types
+export function paginationTarget(header: string | undefined, currentUrl: string | URL, relation: string): URL | null {
+	if (typeof header !== 'string' || header.trim() === '') {
+		return null;
+	}
+
+	for (const {reference, parameters} of parseLinkHeader(header)) {
+		const {rel} = parameters;
+		if (rel === undefined) {
+			continue;
+		}
+
+		const relations = rel.replaceAll('"', '').trim().split(/\s+/);
+		if (relations.includes(relation)) {
+			return new URL(reference, currentUrl);
+		}
+	}
+
+	return null;
+}
diff --git a/test/pagination-target.ts b/test/pagination-target.ts
new file mode 100644
index 0000000..64c6721
--- /dev/null
+++ b/test/pagination-target.ts
@@ -0,0 +1,36 @@
+import test from 'ava';
+import {paginationTarget} from '../source/pagination-target.js';
+
+test('returns the first entry whose rel includes the relation', t => {
+	const header = '<https://api.example.com/items?page=1>; rel="prev", </items?page=3>; rel="next", <https://api.example.com/items?page=9>; rel="last"';
+	t.is(
+		paginationTarget(header, 'https://api.example.com/items?page=2', 'next')?.href,
+		'https://api.example.com/items?page=3',
+	);
+});
+
+test('accepts unquoted and multi-value rel parameters', t => {
+	t.is(
+		paginationTarget('</a>; rel=next, </b>; rel="prev next"', 'https://example.com/x', 'next')?.href,
+		'https://example.com/a',
+	);
+});
+
+test('returns null when the relation is absent', t => {
+	t.is(paginationTarget('<https://example.com/a>; rel="prev"', 'https://example.com', 'next'), null);
+});
+
+test('returns null for absent or whitespace-only headers', t => {
+	t.is(paginationTarget(undefined, 'https://example.com', 'next'), null);
+	t.is(paginationTarget('   ', 'https://example.com', 'next'), null);
+});
+
+test('matches whole rel values only', t => {
+	t.is(paginationTarget('<https://example.com/a>; rel="nextpage"', 'https://example.com', 'next'), null);
+});
+
+test('throws on malformed Link headers', t => {
+	t.throws(() => {
+		paginationTarget('not-a-link-header', 'https://example.com', 'next');
+	});
+});
